#!/usr/bin/env python3
"""Summarize recorded mechanical signals without creating an accuracy score."""
import pathlib,json,statistics,hashlib
root=pathlib.Path(__file__).resolve().parents[2];rounds=root/'research/model-lab/rounds';rows=[]
for name in ['round-1-4b','round-1-small-base','round-2-4b','round-2-adapter','round-3-4b','round-3-adapter','round-3-challenger','heldout-4b','heldout-adapter']:
 rawpath=rounds/(name+'.json');signalpath=rounds/(name+'-content-signals-v2.json')
 if not rawpath.exists() or not signalpath.exists():raise ValueError('Complete raw output and v2 signal files are required: '+name)
 raw=json.loads(rawpath.read_text());signals=json.loads(signalpath.read_text());results=signals['results'];latencies=[x['seconds'] for x in raw['results']]
 if not signals['coverage']['complete']:raise ValueError('Incomplete case coverage: '+name)
 quotes=[q for x in results for q in x['exactQuoteSignals']]
 rows.append({'id':name,'cases':len(results),'strictJSONObjectCount':sum(x['jsonObject'] for x in results),'fenceNormalizedJSONObjectCount':sum(x['normalizedJSONObject'] for x in results),'answerAvailableCount':sum(x['answerAvailable'] for x in results),'allRequiredInlineCitationCount':sum(x['sourceIdentifiers']['allRequiredInline'] for x in results),'casesWithUnknownCitationIDs':sum(bool(x['sourceIdentifiers']['unknown']) for x in results),'exactQuoteMatches':sum(q['exactSubstring'] for q in quotes),'quoteEntries':len(quotes),'quotesOver180Characters':sum(q['characters'] is not None and q['characters']>180 for q in quotes),'emptyActionListCount':sum(x['actionsEmpty'] for x in results),'truncatedCount':sum(x['truncated'] for x in results),'latencySeconds':{'min':min(latencies),'median':statistics.median(latencies),'max':max(latencies),'total':round(sum(latencies),3)},'raw':str(rawpath.relative_to(root)),'rawSHA256':hashlib.sha256(rawpath.read_bytes()).hexdigest(),'signals':str(signalpath.relative_to(root)),'signalsSHA256':hashlib.sha256(signalpath.read_bytes()).hexdigest()})
training=[]
for stage in [2,3]:
 path=rounds/f'round-{stage}-training.json';r=json.loads(path.read_text());training.append({'stage':stage,'steps':r['steps'],'seconds':r['seconds'],'trainableParameters':r['trainableParameters'],'adapterDeltaL2':r['adapterDeltaL2'],'initialParameterSHA256':r['initialParameterSHA256'],'finalParameterSHA256':r['finalParameterSHA256'],'receipt':str(path.relative_to(root))})
report={'kind':'three-round-model-laboratory-summary','rows':rows,'training':training,'actualGenerations':sum(x['cases'] for x in rows),'developmentGenerations':sum(x['cases'] for x in rows if not x['id'].startswith('heldout')),'heldoutGenerations':sum(x['cases'] for x in rows if x['id'].startswith('heldout')),'optimizerUpdates':{'feasibilityProbe':2,'round2':24,'round3ResetBase':24,'totalExecuted':50,'updatesInFinalAdapter':24},'selection':'Source excerpts remain the browser default. The2507 provider is optional; the trained0.6B adapter and Qwen3.5 challenger are experimental and not promoted.','scope':['These are formatting/source-identity/quote-substring counts, not semantic accuracy.','Manual review found arithmetic and source-use failures, including in the final4B heldout responses.','The4B JSON grammar, model precision, prompt profiles and training targets differ across configurations.','Fixed source packets isolate supplied-context generation from the separately rebuilt public retrieval corpus.','No after-heldout tuning was performed.']}
path=root/'research/model-lab/results-summary.json';path.write_text(json.dumps(report,indent=2)+'\n');print(json.dumps({'actualGenerations':report['actualGenerations'],'output':str(path)}))
